package main

import (
"fmt"
"context"
)


func main() {
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()
    done := make(chan struct{})
    result := "waiting"
    go func() {
        defer close(done)
        <-ctx.Done()
        result = "stopped"
    }()
    cancel()
    <-done
    fmt.Println(result)
}

